INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q123560989', 'November 1918 Liechtenstein putsch', 'The 1918 Liechtenstein putsch (German: Novemberputsch 1918), also known as the Beck putsch, was a de facto coup d''état conducted by Wilhelm Beck, Fritz Walser, and Martin Ritter on 7 November against the government of Governor of Liechtenstein, Leopold Freiherr von Imhof. The coup forced Imhof''s government to resign and established a Provisional Executive Committee in his place until 7 December.', 1918, 11, 8, NULL, NULL, NULL, 'day', '8 November 1918', 34, 'https://en.wikipedia.org/wiki/1918_Liechtenstein_putsch'),
  ('Q2653958', 'Liechtenstein alcohol tax referendum', 'A referendum on introducing an alcohol tax was held in Liechtenstein on 26 May 1929. The proposal was approved by 54% of voters.', 1929, 5, 26, NULL, NULL, NULL, 'day', '26 May 1929', 34, 'https://en.wikipedia.org/wiki/1929_Liechtenstein_alcohol_tax_referendum'),
  ('Q6544056', 'Liechtenstein women''s suffrage referendum, 1984', 'A referendum on the introduction of women''s suffrage in national elections was held in Liechtenstein on 1 July 1984. Following the introduction of female suffrage in neighbouring Switzerland at the federal level after a referendum in 1971 (although women had had the right to vote in many cantons and municipalities before this), Liechtenstein had been the only remaining European country to deny women the right to vote.', 1984, 7, 1, NULL, NULL, NULL, 'day', '1 July 1984', 37, 'https://en.wikipedia.org/wiki/1984_Liechtenstein_women''s_suffrage_referendum'),
  ('Q16932702', 'Liechtenstein constitutional referendum, 2003', 'A constitutional referendum regarding the prince''s powers was held in Liechtenstein on 14 March 2003. The referendum had two questions: a "Princely Initiative" and a "Constitution Peace Initiative".', 2003, 3, 14, NULL, NULL, NULL, 'day', '14 March 2003', 41, 'https://en.wikipedia.org/wiki/2003_Liechtenstein_constitutional_referendum'),
  ('Q73356492', '2019 Liechtenstein Hospital referendum', 'A referendum on the financing of a new public hospital in Vaduz was held in Liechtenstein on 24 November 2019. The proposal was approved by 56% of voters.', 2019, 11, 24, NULL, NULL, NULL, 'day', '24 November 2019', 37, 'https://en.wikipedia.org/wiki/2019_Liechtenstein_hospital_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q98609687', '2020 Liechtenstein referendum', 'A three-part referendum was held in Liechtenstein on 30 August 2020. Voters were asked whether they approve of an initiative proposing changes to the constitution to promote the equal representation of women in political bodies, a parliament law allowing dual citizenship for naturalised citizens, and a decision by the government to fund a railway line expansion.', 2020, 8, 30, NULL, NULL, NULL, 'day', '30 August 2020', 37, 'https://en.wikipedia.org/wiki/2020_Liechtenstein_referendum');

